#include <stdio.h>
#include <string.h>
#include "blake3.h"

/* pull in the exact test table from the plugin, stubbing John headers */
#define FMT_EXTERNS_H 0
#define FMT_REGISTERS_H 0

struct fmt_tests {
	const char *ciphertext;
	const char *plaintext;
};

#define FORMAT_TAG "$raw-blake3$"

/* extract just the table by text include */
static const struct fmt_tests blake3_tests[] = {
#include "vectors.inc"
};

int main(void)
{
	int i;

	for (i = 0; blake3_tests[i].ciphertext; i++) {
		const char *ct = blake3_tests[i].ciphertext;
		const char *pt = blake3_tests[i].plaintext;
		blake3_ctx ctx;
		unsigned char out[32];
		int j;

		if (!strncmp(ct, FORMAT_TAG, strlen(FORMAT_TAG)))
			ct += strlen(FORMAT_TAG);

		blake3_init(&ctx);
		blake3_update(&ctx, (const unsigned char *)pt,
		    pt ? strlen(pt) : 0);
		blake3_final(&ctx, out);

		printf("%2d len=%4zu hash=", i, pt ? strlen(pt) : 0);
		for (j = 0; j < 32; j++)
			printf("%02x", out[j]);
		printf(" expected=%s %s\n", ct,
		    !strcmp(ct, (char[65]){0}) ? "" : "");
	}
	return 0;
}

