#include <stdio.h>
#include <string.h>
#include "blake3.h"

struct fmt_tests { const char *ciphertext; const char *plaintext; };
#define FORMAT_TAG "$raw-blake3$"

static const struct fmt_tests blake3_tests[] = {
#include "/tmp/vectors_table.inc"
	{ NULL, NULL }
};

int main(void)
{
	int i, fails = 0;

	for (i = 0; blake3_tests[i].ciphertext; i++) {
		const char *ct = blake3_tests[i].ciphertext;
		const char *pt = blake3_tests[i].plaintext ?
		    blake3_tests[i].plaintext : "";
		blake3_ctx ctx;
		unsigned char out[32];
		char hex[65];
		int j;

		if (!strncmp(ct, FORMAT_TAG, strlen(FORMAT_TAG)))
			ct += strlen(FORMAT_TAG);

		blake3_init(&ctx);
		blake3_update(&ctx, (const unsigned char *)pt, strlen(pt));
		blake3_final(&ctx, out);
		for (j = 0; j < 32; j++)
			sprintf(hex + 2 * j, "%02x", out[j]);

		if (strcmp(hex, ct)) {
			printf("FAIL #%d len=%zu\n  got %s\n exp %s\n",
			    i, strlen(pt), hex, ct);
			fails++;
		} else {
			printf("ok #%2d len=%4zu\n", i, strlen(pt));
		}
	}
	printf("%d entries, %d failures\n", i, fails);
	return fails != 0;
}

